namespace sv_7c6d375c3e1f46b7a883b0f2c45e1829.Services;

public record JobApplication(PersonalInfo Personal, WorkHistory Work, List<Reference> References, string CoverLetter);
public record PersonalInfo(string FullName, string Email, string Phone, string Address);
public record WorkHistory(List<WorkEntry> Entries);
public record WorkEntry(string Company, string Title, DateTime StartDate, DateTime? EndDate, string Description);
public record Reference(string Name, string Relationship, string Email, string Phone);

public interface IApplicationService
{
    Task<int> SubmitApplicationAsync(JobApplication application);
    Task<bool> ValidateEmailAsync(string email);
}

.application-form {
    max-width: 800px;
    margin: 0 auto;
    padding: 2rem;
}

.application-form h1 {
    text-align: center;
    margin-bottom: 2rem;
    color: #1a1a2e;
}

/* Step Indicator */
.step-indicator {
    display: flex;
    align-items: center;
    justify-content: center;
    margin-bottom: 2rem;
    padding: 1rem 0;
}

.step {
    display: flex;
    flex-direction: column;
    align-items: center;
    cursor: default;
    transition: opacity 0.3s;
}

.step.completed {
    cursor: pointer;
}

.step.dimmed {
    opacity: 0.4;
}

.step-circle {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-weight: bold;
    font-size: 0.9rem;
    margin-bottom: 0.4rem;
    border: 2px solid #ccc;
    background: white;
    color: #666;
    transition: all 0.3s;
}

.step.active .step-circle {
    background: #4361ee;
    border-color: #4361ee;
    color: white;
}

.step.completed .step-circle {
    background: #2ec4b6;
    border-color: #2ec4b6;
    color: white;
}

.step-label {
    font-size: 0.75rem;
    color: #666;
    text-align: center;
    max-width: 80px;
}

.step.active .step-label {
    color: #4361ee;
    font-weight: 600;
}

.step.completed .step-label {
    color: #2ec4b6;
}

.step-connector {
    flex: 1;
    height: 2px;
    background: #ddd;
    margin: 0 0.5rem;
    margin-bottom: 1.2rem;
    min-width: 30px;
    max-width: 60px;
}

.checkmark {
    font-size: 1rem;
}

/* Form Content */
.step-content {
    background: white;
    border-radius: 12px;
    padding: 2rem;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
}

.step-content h2 {
    margin-bottom: 1.5rem;
    color: #1a1a2e;
}

.section-description {
    color: #666;
    margin-bottom: 1.5rem;
}

.form-group {
    margin-bottom: 1.2rem;
}

.form-group label {
    display: block;
    margin-bottom: 0.4rem;
    font-weight: 500;
    color: #333;
    font-size: 0.9rem;
}

.form-group input[type="text"],
.form-group input[type="email"],
.form-group input[type="tel"],
.form-group input[type="date"],
.form-group textarea {
    width: 100%;
    padding: 0.6rem 0.8rem;
    border: 1px solid #ddd;
    border-radius: 6px;
    font-size: 0.95rem;
    transition: border-color 0.2s;
    box-sizing: border-box;
}

.form-group input:focus,
.form-group textarea:focus {
    outline: none;
    border-color: #4361ee;
    box-shadow: 0 0 0 3px rgba(67, 97, 238, 0.1);
}

.form-group textarea {
    min-height: 80px;
    resize: vertical;
}

.form-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 1rem;
}

.checkbox-group {
    display: flex;
    align-items: center;
    gap: 0.5rem;
}

.checkbox-group input[type="checkbox"] {
    width: auto;
}

.checkbox-group label {
    display: inline;
    margin-bottom: 0;
    font-weight: normal;
}

/* Cards */
.work-entry-card,
.reference-card {
    border: 1px solid #e8e8e8;
    border-radius: 8px;
    padding: 1.5rem;
    margin-bottom: 1rem;
    background: #fafafa;
}

.work-entry-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 1rem;
}

.work-entry-header h3 {
    margin: 0;
    color: #333;
    font-size: 1.1rem;
}

/* Buttons */
.form-actions {
    display: flex;
    justify-content: space-between;
    margin-top: 2rem;
    padding-top: 1.5rem;
    border-top: 1px solid #eee;
}

.btn-next,
.btn-submit {
    background: #4361ee;
    color: white;
    border: none;
    padding: 0.7rem 2rem;
    border-radius: 6px;
    font-size: 1rem;
    cursor: pointer;
    font-weight: 500;
    transition: background 0.2s;
    margin-left: auto;
}

.btn-next:hover,
.btn-submit:hover {
    background: #3651d4;
}

.btn-next:disabled,
.btn-submit:disabled {
    background: #a0a0a0;
    cursor: not-allowed;
}

.btn-back {
    background: transparent;
    color: #666;
    border: 1px solid #ddd;
    padding: 0.7rem 2rem;
    border-radius: 6px;
    font-size: 1rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-back:hover {
    border-color: #999;
    color: #333;
}

.btn-add {
    background: transparent;
    color: #4361ee;
    border: 1px dashed #4361ee;
    padding: 0.6rem 1.2rem;
    border-radius: 6px;
    font-size: 0.9rem;
    cursor: pointer;
    width: 100%;
    margin-top: 0.5rem;
    transition: all 0.2s;
}

.btn-add:hover {
    background: #f0f4ff;
}

.btn-remove {
    background: transparent;
    color: #e74c3c;
    border: 1px solid #e74c3c;
    padding: 0.3rem 0.8rem;
    border-radius: 4px;
    font-size: 0.8rem;
    cursor: pointer;
    transition: all 0.2s;
}

.btn-remove:hover {
    background: #fef0f0;
}

.btn-edit {
    background: transparent;
    color: #4361ee;
    border: none;
    padding: 0.3rem 0.6rem;
    font-size: 0.85rem;
    cursor: pointer;
    text-decoration: underline;
}

.btn-edit:hover {
    color: #3651d4;
}

/* Cover Letter */
.cover-letter-input {
    min-height: 200px !important;
    font-family: inherit;
}

.character-count {
    text-align: right;
    font-size: 0.85rem;
    color: #888;
    margin-top: 0.4rem;
}

.character-count.warning {
    color: #e74c3c;
    font-weight: 500;
}

/* Review Section */
.review-section {
    border: 1px solid #e8e8e8;
    border-radius: 8px;
    padding: 1.2rem;
    margin-bottom: 1rem;
}

.review-header {
    display: flex;
    justify-content: space-between;
    align-items: center;
    margin-bottom: 0.8rem;
    padding-bottom: 0.5rem;
    border-bottom: 1px solid #eee;
}

.review-header h3 {
    margin: 0;
    font-size: 1rem;
    color: #333;
}

.review-content p {
    margin: 0.3rem 0;
    font-size: 0.9rem;
    color: #555;
}

.review-work-entry,
.review-reference {
    padding: 0.6rem 0;
    border-bottom: 1px solid #f5f5f5;
}

.review-work-entry:last-child,
.review-reference:last-child {
    border-bottom: none;
}

.cover-letter-preview {
    white-space: pre-wrap;
    background: #f9f9f9;
    padding: 0.8rem;
    border-radius: 4px;
    font-size: 0.9rem;
}

/* Error & Confirmation */
.error-message {
    background: #fef0f0;
    border: 1px solid #f5c6cb;
    color: #e74c3c;
    padding: 0.8rem 1rem;
    border-radius: 6px;
    margin-bottom: 1rem;
    font-size: 0.9rem;
}

.confirmation {
    text-align: center;
    padding: 3rem 2rem;
    background: white;
    border-radius: 12px;
    box-shadow: 0 2px 12px rgba(0, 0, 0, 0.08);
}

.confirmation h2 {
    color: #2ec4b6;
    margin-bottom: 1rem;
}

.confirmation p {
    color: #555;
    font-size: 1.1rem;
}

